<?php
require_once dirname(__DIR__).'/includes/functions.php';require_role(['student','counselor']);$id=(int)($_GET['id']??0);$stmt=$con->prepare('SELECT q.*,c.title career FROM quizzes q JOIN careers c ON c.id=q.career_id WHERE q.id=? AND q.is_active=1');$stmt->bind_param('i',$id);$stmt->execute();$quiz=$stmt->get_result()->fetch_assoc();if(!$quiz){http_response_code(404);exit('Quiz not found');}$stmt=$con->prepare('SELECT * FROM quiz_questions WHERE quiz_id=? ORDER BY sort_order,id');$stmt->bind_param('i',$id);$stmt->execute();$questions=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);if(count($questions)<10){flash('info','This quiz is still being prepared and needs at least 10 questions.');header('Location:'.url('quiz/choose.php?career_id='.$quiz['career_id']));exit;}foreach($questions as &$q){$s=$con->prepare('SELECT id,option_text FROM quiz_options WHERE question_id=? ORDER BY sort_order,id');$s->bind_param('i',$q['id']);$s->execute();$q['options']=$s->get_result()->fetch_all(MYSQLI_ASSOC);}unset($q);$pageTitle=$quiz['title'];require dirname(__DIR__).'/includes/header.php';?>
<div class="container py-5"><div class="d-flex justify-content-between align-items-center mb-3"><div><div class="text-muted"><?=e($quiz['career'])?></div><h1><?=e($quiz['title'])?></h1></div><div class="badge bg-primary fs-6"><i class="bi bi-clock"></i> <span id="timer"><?=$quiz['time_limit_minutes']?>:00</span></div></div><form class="card p-4" action="<?=url('quiz/submit.php')?>" method="post" data-ajax id="quizForm"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="quiz_id" value="<?=$id?>"><?php if(!$questions):?><div class="alert alert-info">This quiz has no questions.</div><?php endif?><?php foreach($questions as $i=>$q):?><fieldset class="mb-4"><legend class="h6"><?=$i+1?>. <?=e($q['question_text'])?> <span class="text-muted">(<?=$q['points']?> pts)</span></legend><?php foreach($q['options'] as $o):?><label class="form-check border rounded p-3 mb-2"><input class="form-check-input ms-0 me-2" type="<?=$q['question_type']==='multiple_choice'?'checkbox':'radio'?>" name="answers[<?=$q['id']?>]<?=$q['question_type']==='multiple_choice'?'[]':''?>" value="<?=$o['id']?>"><span><?=e($o['option_text'])?></span></label><?php endforeach?></fieldset><?php endforeach?><?php if($questions):?><button class="btn btn-primary">Submit quiz</button><?php endif?></form></div><script>let remaining=<?=$quiz['time_limit_minutes']*60?>;const tick=setInterval(()=>{remaining--;timer.textContent=Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0');if(remaining<=0){clearInterval(tick);quizForm.requestSubmit()}},1000)</script><?php require dirname(__DIR__).'/includes/footer.php';?>
